const response = $input.first().json || {};
const input = $('Normalizar y validar entrada').first().json;
const status = Number(response.statusCode ?? 0);
const board = response.body || {};
const failed = status < 200 || status >= 300 || !Array.isArray(board.cards) || !Array.isArray(board.lists) || !Array.isArray(board.members);
if (failed) return [{ json: { ...input, ok: false, status_code: status || 503, error: 'Trello no devolvió un tablero válido.', tarjetas: [], tarjetas_operativas: [] } }];
const allowedById = new Map([
  ['REEMPLAZAR_ID_LISTA_PARA_HACER', 'Para hacer'],
  ['REEMPLAZAR_ID_LISTA_EN_CURSO', 'En curso'],
  ['REEMPLAZAR_ID_LISTA_ESPERANDO', 'Esperando de otros'],
  ['REEMPLAZAR_ID_LISTA_VALIDACION', 'Validación'],
  ['REEMPLAZAR_ID_LISTA_EN_DESARROLLO', 'En Desarrollo']
]);
const lists = new Map(board.lists
  .filter(l => !l.closed && allowedById.has(l.id))
  .map(l => [l.id, allowedById.get(l.id)]));
if (lists.size !== allowedById.size) return [{ json: { ...input, ok: false, status_code: 503,
  error: 'Faltan listas operativas en el tablero de Trello.', tarjetas: [], tarjetas_operativas: [] } }];
const members = new Map(board.members.map(m => [m.id, String(m.fullName || '').trim()]));
const local = dt => {
  const parts = new Intl.DateTimeFormat('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(dt);
  const p = Object.fromEntries(parts.map(part => [part.type, part.value]));
  return `${p.year}-${p.month}-${p.day}`;
};
const today = local(new Date());
const records = board.cards.filter(c => !c.closed && lists.has(c.idList)).map(c => {
  const fullDesc = String(c.desc || '');
  const next = fullDesc.match(/(?:^|\n)\s*(?:[-•]\s*)?\**\s*pr[oó]xim[oa]\s+(?:paso|acci[oó]n(?:\s+clave)?)\**\s*[:：–—-]\**\s*([^\n\r]+)/i);
  const due = c.due || null;
  const validDate = due && Number.isFinite(new Date(due).getTime());
  const date = validDate ? local(new Date(due)) : null;
  const responsibles = (Array.isArray(c.idMembers) ? c.idMembers : []).map(id => members.get(id) || 'Responsable no identificado').join(', ') || 'Sin asignar';
  return {
    id: String(c.id || ''), name: String(c.name || ''), lista: lists.get(c.idList),
    responsables: responsibles, due, fecha_seguimiento: date,
    shortUrl: String(c.shortUrl || ''),
    proximo_paso: next ? next[1].trim().slice(0, 300) : 'No explicitado en la tarjeta',
    contexto: fullDesc.replace(/\s+/g, ' ').slice(0, 200),
    desc: fullDesc.slice(0, 540), fecha_invalida: Boolean(due && !validDate)
  };
});
const byDate = (a, b) => (a.fecha_seguimiento || '9999-99-99').localeCompare(b.fecha_seguimiento || '9999-99-99') || a.name.localeCompare(b.name, 'es');
records.sort(byDate);
const todayOnly = records.filter(c => c.fecha_seguimiento === today);
const older = records.filter(c => c.fecha_seguimiento && c.fecha_seguimiento < today);
const future = records.filter(c => c.fecha_seguimiento && c.fecha_seguimiento > today);
const noDate = records.filter(c => !c.due);
const invalid = records.filter(c => c.fecha_invalida);
return [{ json: {
  ...input, ok: true, status_code: 200, fecha: today,
  total_tarjetas: board.cards.length, total_operativas: records.length,
  cantidad_seguimientos: todayOnly.length + older.length,
  cantidad_hoy: todayOnly.length, cantidad_anteriores: older.length,
  cantidad_futuros: future.length, cantidad_sin_fecha: noDate.length,
  cantidad_fechas_invalidas: invalid.length,
  tarjetas: [...todayOnly, ...older], tarjetas_hoy: todayOnly,
  tarjetas_anteriores: older, tarjetas_futuras: future,
  tarjetas_sin_fecha: noDate, tarjetas_fecha_invalida: invalid,
  tarjetas_operativas: records
} }];

