const d = $input.first().json;
const msg = String(d.mensaje || '').trim();
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[¿?¡!.,;:]/g, ' ').replace(/\s+/g, ' ').trim();
const q = norm(msg);
const all = d.tarjetas_operativas || [];
const escritura = /\b(mover|mov[eé]|modificar|cambiar|actualizar|eliminar|borrar|crear|editar|cerrar|archivar|reasignar|enviar|mandar|publicar)\b/.test(q);
if (escritura && /tarjeta|trello|curso|proyecto|tarea|estado|lista/.test(q)) return [{json:{...d,resultado_deterministico:false}}];
const date = d.fecha;
const pageMatch = q.match(/\bpag(?:ina)?\s*(\d+)\b/);
const page = pageMatch ? Number(pageMatch[1]) : 1;
const compact = v => String(v || '').replace(/\s+/g, ' ').trim();
const prettyDate = iso => iso ? `${iso.slice(8,10)}/${iso.slice(5,7)}/${iso.slice(0,4)}` : 'Sin fecha';
function respond(text, action='responder') {
  return [{ json: { ...d, resultado_deterministico: true, accion: action, respuesta: text, fuente: 'Trello', status_code: 200 } }];
}
function cards(title, items, extra='') {
  if (!items.length) return respond(`${title}. No se encontraron tarjetas en las cinco listas operativas.${extra ? '\n' + extra : ''}`);
  const rows = items.map((t, i) => {
    const timing = t.fecha_seguimiento ? (t.fecha_seguimiento < date ? 'anterior para revisar' : t.fecha_seguimiento === date ? 'de hoy' : 'futuro') : 'sin fecha';
    return `${i + 1}. ${compact(t.name)}\nEstado: ${t.lista} | Responsable: ${compact(t.responsables)}\nSeguimiento: ${prettyDate(t.fecha_seguimiento)} (${timing})\nPróximo paso: ${compact(t.proximo_paso)}${t.shortUrl ? '\nTrello: ' + t.shortUrl : ''}`;
  });
  const chunks = [];
  let chunk = [];
  let chars = 0;
  for (const item of rows) {
    if (chunk.length && (chunk.length >= 8 || chars + item.length + 2 > 2900)) {
      chunks.push(chunk); chunk = []; chars = 0;
    }
    chunk.push(item); chars += item.length + 2;
  }
  if (chunk.length) chunks.push(chunk);
  if (!Number.isSafeInteger(page) || page < 1 || page > chunks.length) {
    return respond(`Hay ${items.length} tarjetas y ${chunks.length} página(s) para «${title}». Indicá una página entre 1 y ${chunks.length}.`, 'aclarar');
  }
  const intro = `${title} (${prettyDate(date)})\nTotal: ${items.length} tarjeta(s).${extra ? '\n' + extra : ''}\nPágina ${page} de ${chunks.length}.`;
  const more = page < chunks.length ? `\n\nPara continuar: «${msg.replace(/\s+pag(?:ina)?\s*\d+\b/i, '').trim()} página ${page + 1}».` : '';
  return respond(intro + '\n\n' + chunks[page - 1].join('\n\n') + more);
}
const listNames = ['Para hacer', 'En curso', 'Esperando de otros', 'Validación', 'En Desarrollo'];
const isDocs = /\b(roi|rag|preentrega|metodologia|academico|embeddings)\b/.test(q);
if (isDocs) return [{ json: { ...d, resultado_deterministico: true, accion: 'aclarar', respuesta: 'Este asistente consulta tareas y seguimientos de Trello. El análisis de ROI y las preentregas académicas se encuentran en el README del proyecto, no en el tablero.', fuente: 'ninguna', status_code: 200 } }];
if (/\b(hoy|del dia|para el dia)\b/.test(q) && /seguimiento|tarea|tarjeta|que tengo|que hay|pendiente/.test(q)) {
  const strict = /\b(solo|solamente|exactamente|unicamente)\s+(?:para\s+)?hoy\b/.test(q);
  return cards(strict ? 'Seguimientos fechados exactamente hoy' : 'Seguimientos para revisar hoy', strict ? d.tarjetas_hoy : d.tarjetas,
    strict ? '' : `${d.cantidad_hoy} con fecha de hoy y ${d.cantidad_anteriores} con fecha anterior. «Due» es seguimiento, no entrega vencida.`);
}
if (/\b(vencid[oa]s?|atrasad[oa]s?|anteriores|pasad[oa]s?)\b/.test(q) && /seguimiento|tarea|tarjeta|fecha/.test(q)) {
  return cards('Seguimientos con fecha anterior a hoy', d.tarjetas_anteriores, 'Son fechas de revisión anteriores; no implica que una entrega esté incumplida.');
}
if (/\b(pendientes?|para revisar)\b/.test(q) && /\bseguimiento(s)?\b/.test(q)) {
  return cards('Seguimientos pendientes de revisión (hasta hoy)', d.tarjetas,
    `${d.cantidad_hoy} de hoy y ${d.cantidad_anteriores} anteriores.`);
}
if (/\b(proxim[oa]s?|futur[oa]s?|mas adelante|siguientes)\b/.test(q) && /seguimiento|tarea|fecha|tarjeta/.test(q)) {
  return cards('Próximos seguimientos futuros', d.tarjetas_futuras);
}
if (/\b(manana)\b/.test(q) && /seguimiento|tarea|tarjeta/.test(q)) {
  const next = new Date(date + 'T12:00:00Z'); next.setUTCDate(next.getUTCDate() + 1);
  return cards('Seguimientos de mañana', all.filter(t => t.fecha_seguimiento === next.toISOString().slice(0,10)));
}
if (/\b(sin fecha|no tienen fecha|sin seguimiento programado)\b/.test(q)) {
  return cards('Tarjetas sin fecha de seguimiento', d.tarjetas_sin_fecha);
}
if (/\b(cuantas|cuantos|total|cantidad|numero)\b/.test(q) && /\b(tarjetas|tareas|operativas|listas operativas)\b/.test(q) && !/\b(hoy|seguimientos|responsable|lista|proxim|vencid)\b/.test(q.replace('listas operativas', ''))) {
  return respond(`Hay ${d.total_operativas} tarjetas abiertas en las cinco listas operativas de Trello. El tablero devolvió ${d.total_tarjetas} tarjetas en total, incluidas otras listas. ${d.cantidad_seguimientos} tienen fecha de seguimiento hoy o anterior (${d.cantidad_hoy} hoy, ${d.cantidad_anteriores} anteriores).`);
}
const mentionedList = listNames.find(name => q.includes(norm(name)));
if (mentionedList && /\b(lista|tarjetas|tareas|hay|mostra|mostrame|cuantas|cuantos|que hay)\b/.test(q)) {
  const matches = all.filter(t => norm(t.lista) === norm(mentionedList));
  if (/\b(cuantas|cuantos|cantidad|total)\b/.test(q)) return respond(`La lista «${mentionedList}» contiene ${matches.length} tarjeta(s) abiertas.`);
  return cards(`Tarjetas de «${mentionedList}»`, matches);
}
const wantsPerson = /\b(responsable|asignad|quien tiene|tiene|tareas de|tarjetas de|que lleva|a cargo de)\b/.test(q);
if (wantsPerson) {
  const personFragment = q.match(/(?:tareas|tarjetas) de\s+(.+?)(?:\s+pag(?:ina)?\s*\d+)?$/)?.[1]
    || q.match(/(?:tiene|lleva|cargo de|responsable es|asignad[oa]s? a)\s+(.+?)(?:\s+pag(?:ina)?\s*\d+)?$/)?.[1];
  if (personFragment) {
    const candidate = personFragment.replace(/^(el|la|los|las)\s+/, '').replace(/\s+\b(hoy|pendiente|en trello)\b.*$/, '').trim();
    const names = [...new Set(all.flatMap(t => t.responsables === 'Sin asignar' ? [] : t.responsables.split(',').map(x => x.trim())))];
    const matching = names.filter(n => norm(n).split(/\s+/).some(p => p === candidate) || norm(n).includes(candidate));
    if (matching.length === 1) return cards(`Tarjetas de ${matching[0]}`, all.filter(t => t.responsables.split(',').some(p => norm(p.trim()) === norm(matching[0]))));
    if (matching.length > 1) return respond(`Encontré varios responsables: ${matching.join(', ')}. ¿A cuál te referís?`, 'aclarar');
  }
}
const projectMatch = q.match(/\b(?:proyecto|tema|sobre|estado de|como va|que pasa con|del proyecto)\s+(?:el\s+|la\s+)?(.+?)(?:\s+pag(?:ina)?\s*\d+)?$/);
if (projectMatch) {
  const term = projectMatch[1].replace(/^(proyecto|tema|de|del)\s+/, '').trim();
  if (term.length >= 4) {
    const matches = all.filter(t => norm(t.name).includes(term));
    if (matches.length) return cards(`Tarjetas relacionadas con «${term}»`, matches);
  }
}
return [{ json: { ...d, resultado_deterministico: false } }];

const d = $input.first().json;
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const q = norm(d.mensaje || '');
const docs = /\b(roi|rag|preentrega|metodologia|curso|academico|prompt|embeddings|arquitectura|procedimiento|procedimientos|criterios|normas|politicas|reglas|como funciona|como se determina|como se calcula|como se prepara|manual|documentacion|ahorro de tiempo)\b/.test(q);
const tokens = q.split(/[^a-z0-9]+/).filter(w => w.length >= 4 && !['como','cual','cuanto','tarea','tareas','tarjeta','tarjetas','sobre','tiene','estado','consulta','lista','responsable','hacer','quiero'].includes(w));
const cards = (d.tarjetas_operativas || []).map(t => ({
  name: t.name, lista: t.lista, responsables: t.responsables,
  fecha_seguimiento: t.fecha_seguimiento, proximo_paso: t.proximo_paso,
  contexto: String(t.contexto || '').slice(0, 130), enlace: t.shortUrl
}));
const ranked = cards.map(t => ({ t, score: tokens.reduce((v, w) => v + (norm(t.name).includes(w) ? 5 : 0) + (norm(t.responsables).includes(w) ? 3 : 0) + (norm(t.proximo_paso).includes(w) ? 2 : 0) + (norm(t.contexto).includes(w) ? 1 : 0), 0) })).filter(p => p.score > 0).sort((a,b) => b.score - a.score);
const selected = docs ? [] : ranked.slice(0, 10).map(x => x.t);
return [{ json: { ...d, contexto_ia: JSON.stringify(selected), contexto_resultados: selected.length, consulta_documental: docs, contexto_rag: '', fuentes_rag: [], rag_recuperado: false } }];

const d = $input.first().json;
const tarjetas_resumidas = (d.tarjetas || []).map(t => ({
  name: t.name, lista: t.lista, responsables: t.responsables,
  fecha_seguimiento: t.fecha_seguimiento, proximo_paso: t.proximo_paso,
  situacion: t.desc.slice(0, 330), shortUrl: t.shortUrl
}));
return [{ json: { ...d, tarjetas_resumidas } }];

const d = $('Seleccionar seguimientos y responsables').first().json;
const incoming = $input.first().json || {};
let cuerpo = String(incoming.cuerpo || '').trim();
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g, ' ').trim();
const all = d.tarjetas || [];
const normalizedBody = norm(cuerpo);
const escapeRegExp = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const missing = all.filter(t => !new RegExp(`(^|[^a-z0-9])${escapeRegExp(norm(t.name))}(?=$|[^a-z0-9])`).test(normalizedBody));
const incorrect = !cuerpo || missing.length > 0 || /```|\{"accion"/.test(cuerpo);
if (incorrect) {
  const format = t => `${t.name}\nEstado: ${t.lista}\nResponsables: ${t.responsables}\nFecha de seguimiento: ${t.fecha_seguimiento || 'Sin fecha'}\nSituación: ${t.contexto || 'Sin descripción disponible'}\nPróximo paso: ${t.proximo_paso}\nTrello: ${t.shortUrl || 'Sin enlace'}`;
  cuerpo = `SEGUIMIENTOS PARA HOY - ${d.fecha}\nTotal: ${all.length}. De hoy: ${d.cantidad_hoy}. Con fecha anterior: ${d.cantidad_anteriores}.\nLa fecha corresponde a seguimiento, no a entrega vencida.\n\n` + all.map(format).join('\n\n');
}
return [{ json: { asunto: incoming.asunto || `Seguimientos para hoy - ${d.fecha}`, cuerpo, cobertura_completa: true, respaldo_deterministico: incorrect } }];

const d=$('Preparar contexto acotado para IA').first().json;
const out=$input.all().map(x=>x.json||{});
const readContent=(x)=>{
  const d=x.document||x.doc||{};
  const text=x.pageContent||d.pageContent||d.page_content||x.text||x.content||'';
  const meta=x.metadata||d.metadata||{};
  return {texto:String(text).slice(0,1600), fuente:String(meta.fuente||'Síntesis de las preentregas'), puntuacion:typeof x.score==='number'?x.score:null};
};
const docs=out.map(readContent).filter(z=>z.texto.trim()).slice(0,4);
const context=docs.map((v,i)=>`FUENTE ${i+1}: ${v.fuente}\n${v.texto}`).join('\n\n');
return [{json:{...d,contexto_rag:context,fuentes_rag:docs.map(v=>v.fuente),rag_recuperado:docs.length>0}}];

parameters.jsonOutput:
={{ JSON.stringify({
  decision_ia: (() => {
    const raw = $json.output;
    if (raw && typeof raw === 'object') return raw;
    const s = String(raw ?? '').trim()
      .replace(/^\`\`\`(?:json)?\s*/i, '')
      .replace(/\`\`\`\s*$/, '');
    try {
      const parsed = JSON.parse(s);
      return typeof parsed === 'string' ? JSON.parse(parsed) : parsed;
    } catch {
      return { accion: 'derivar', respuesta: '', fuente: 'ninguna' };
    }
  })()
}) }}
